'use client'
/** Loaders: the MATRIX card `ui-loaders` (interactive: pointer and keyboard edit its data). Generated by scripts/registry/generate.ts. */
import { MatrixDotCard, type MatrixDotCardProps } from '@/components/matrix/dot-card'
import { componentsBoard } from '@/lib/matrix/widgets/boards/components'

const preset = componentsBoard.find(p => p.id === 'ui-loaders')!

export type MatrixLoadersProps = Omit<MatrixDotCardProps, 'preset'>

export function MatrixLoaders(props: MatrixLoadersProps) {
  return <MatrixDotCard preset={preset} {...props} />
}
